// Sport key → color map. Same short + full key patterns as teamLogos.js
// so callers can pass either the app's short sport ('nfl') or a full
// odds-API key ('americanfootball_nfl').
const SPORT_MAP = {
  nfl: NFL_COLORS, americanfootball_nfl: NFL_COLORS,
  americanfootball_nfl_preseason: NFL_COLORS,
  nba: NBA_COLORS, basketball_nba: NBA_COLORS,
  wnba: WNBA_COLORS, basketball_wnba: WNBA_COLORS,
  mlb: MLB_COLORS, baseball_mlb: MLB_COLORS,
  nhl: NHL_COLORS, icehockey_nhl: NHL_COLORS,
  mls: MLS_COLORS, soccer_usa_mls: MLS_COLORS,
  ufl: UFL_COLORS, americanfootball_ufl: UFL_COLORS,
  ncaaf: NCAAF_COLORS, americanfootball_ncaaf: NCAAF_COLORS,
  ncaab: NCAAB_COLORS, basketball_ncaab: NCAAB_COLORS,
  wncaab: WNCAAB_COLORS, basketball_wncaab: WNCAAB_COLORS,
}

// Strip diacritics, straighten quotes, lowercase. Bridges name mismatches
// between odds sources ("San Jose State") and ESPN ("San José State").
function normalizeName(s) {
  if (!s) return ''
  return s
    .normalize('NFD').replace(/[̀-ͯ]/g, '')
    .replace(/[ʻʼ‘’]/g, "'")
    .replace(/'/g, '')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase()
}

const _normCache = new WeakMap()
function normalizedLookup(map, teamName) {
  if (!map || !teamName) return null
  if (map[teamName] != null) return map[teamName]
  let cached = _normCache.get(map)
  if (!cached) {
    cached = {}
    for (const k of Object.keys(map)) cached[normalizeName(k)] = map[k]
    _normCache.set(map, cached)
  }
  return cached[normalizeName(teamName)] ?? null
}

// Look up a team's primary color by sport + team name OR abbreviation.
// Returns a #rrggbb string or null when the sport/team isn't covered.
// Pure black (#000000) is preserved — some teams (Raiders, Bruins) do
// use it, and callers can choose their own fallback for that case.
export function getTeamColor(sportKey, team) {
  if (!sportKey || !team) return null
  const map = SPORT_MAP[sportKey]
  if (!map) return null
  return normalizedLookup(map, team)
}
